    /// <summary>Bounds of the "AVR" lettering in viewBox units.</summary>
    public static readonly Rect AvrBounds = new(43.80, 25.03, 56.35, 20.03);
    /// <summary>Bounds of the whole artwork (script + AVR) in viewBox units.</summary>
    public static readonly Rect LogoBounds = new(30.21, 10.09, 69.94, 34.97);
    /// <summary>Width / height of the artwork: scale both sides by the same factor.</summary>
    public static double AspectRatio => LogoBounds.Width / LogoBounds.Height;

    /// <summary>The SVG fills with the non-zero rule ("F1" in WPF path markup).</summary>
    public static Geometry Parse(string data)
    {
        var g = Geometry.Parse("F1 " + data);
        g.Freeze();
        return g;
    }

    /// <summary>
    /// The full logo in its own colours (black script, #731012 AVR) for a light background.
    /// A DrawingImage sizes itself to the drawing's bounds, so an Image with Stretch="Uniform"
    /// shows the artwork without the viewBox's empty margin and without distortion.
    /// </summary>
    public static DrawingImage CreateLogoImage()
    {
        var group = new DrawingGroup();
        group.Children.Add(new GeometryDrawing(Frozen(Colors.Black), null, Parse(ScriptPathData)));
        group.Children.Add(new GeometryDrawing(Frozen(BrandColor), null, Parse(AvrPathData)));
        group.Freeze();
        var img = new DrawingImage(group);
        img.Freeze();
        return img;
    }

    /// <summary>The header logo (bound with x:Static in MainWindow.xaml).</summary>
    public static DrawingImage LogoImage { get; } = CreateLogoImage();

    private static SolidColorBrush Frozen(Color c)
    {
        var b = new SolidColorBrush(c);
        b.Freeze();
        return b;
    }
}
